    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    let active = 0;
    let timer  = null;
    const AUTOPLAY_MS = 4000;

    function setCTA(i){
      const url = links[i]?.dataset.url || links[i]?.getAttribute('href');
      if (!cta || !url) return
      cta.setAttribute('href', url);
      const yPosition = links[i]?.getBoundingClientRect().top - list.getBoundingClientRect().top + list.scrollTop;
      if (yPosition !== undefined) {
        cta.style.setProperty('transform', `translateY(${yPosition}px)`);
      }
    }

    function goTo(i){
